import {createPronunciationPlayer} from './audio.js';
import {words,decks} from './words.js';
import {dayKey,review,queueFor} from './learning.js';
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1Zm0 0v15"/>',chart:'<path d="M4 20h17M7 16v-5m5 5V4m5 12V8"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5Zm5 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',check:'<path d="m5 12 4 4L19 6"/>',flame:'<path d="M13 2c1 7-5 6-3 11 2-1 3-3 3-3 6 4 6 11-1 12C2 21 3 12 7 8c0 4 2 4 2 4-1-5 4-10 4-10Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',star:'<path d="m12 3 3 6 6 1-4.5 4.5L18 21l-6-3-6 3 1.5-6.5L3 10l6-1z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',leaf:'<path d="M20 3C8 2 2 9 6 16c6 7 16-2 14-13ZM5 20 16 8"/>',chevron:'<path d="m9 5 7 7-7 7"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.star}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem('kioku-v1'))}catch{}state={records:{},days:{},bookmarks:[],goal:10,...state};
let account=null,serverAuth=false,saveQueue=Promise.resolve(),authMode='signin';
let page='home',selected='pre1',session=null,filter='all',search='',modal=null;
const save=()=>{if(account){const snapshot=JSON.stringify(state);saveQueue=saveQueue.then(async()=>{const r=await fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot});if(!r.ok)throw Error()}).catch(()=>toast('サーバーへの保存に失敗しました。接続を確認してもう一度操作してください。'));return}try{localStorage.setItem('kioku-v1',JSON.stringify(state))}catch{toast('保存できません。ブラウザの保存設定をご確認ください。')}};
const today=()=>state.days[dayKey()]||0;
function streak(){let count=0,d=new Date();if(!state.days[dayKey(d)])d.setDate(d.getDate()-1);while(state.days[dayKey(d)]){count++;d.setDate(d.getDate()-1)}return count;}
const learned=deck=>words.filter(w=>(!deck||w.deck===deck)&&(state.records[w.id]?.level||0)>=2).length;
const due=()=>words.filter(w=>state.records[w.id]?.due<=Date.now()).length;
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3000)}
const mascot=(small=false,kind='mint')=>{const c=kind==='berry'?['#a18bff','#e7dcff','#5d449d']:kind==='peach'?['#ffb88b','#ffe3c5','#bc643d']:['#9ae0bd','#def7c6','#317359'];return `<svg class="mascot ${small?'small':''} ${kind}" viewBox="0 0 230 230" fill="none" aria-hidden="true"><ellipse cx="115" cy="213" rx="74" ry="10" fill="${c[2]}" opacity=".12"/><path d="M67 76 57 29q26-3 38 30M142 58q18-34 40-29l-13 50" fill="${c[0]}" stroke="${c[2]}" stroke-width="3.5" stroke-linejoin="round"/><path d="m67 43 8 24m91-24-9 24" stroke="${c[1]}" stroke-width="7" stroke-linecap="round"/><path d="M47 113c0-44 29-68 68-68s69 24 69 68v43c0 34-30 48-69 48s-68-14-68-48z" fill="${c[0]}" stroke="${c[2]}" stroke-width="3.5"/><ellipse cx="115" cy="156" rx="47" ry="34" fill="${c[1]}"/><path d="M47 135q-28-17-29 5 2 15 29 13m137-18q25-27 30-7 5 15-29 26" fill="${c[0]}" stroke="${c[2]}" stroke-width="3.5" stroke-linecap="round"/><path d="M74 197v12q13 10 27-3m32 0q15 13 28 1v-10" fill="${c[0]}" stroke="${c[2]}" stroke-width="3.5"/><ellipse cx="89" cy="106" rx="7" ry="9" fill="#30344d"/><ellipse cx="143" cy="106" rx="7" ry="9" fill="#30344d"/><circle cx="91" cy="103" r="2.3" fill="white"/><circle cx="145" cy="103" r="2.3" fill="white"/><path d="M102 121q14 22 28 0z" fill="#885470"/><path d="M110 131q7-6 13 0" stroke="#ffa7bc" stroke-width="4" stroke-linecap="round"/><ellipse cx="73" cy="122" rx="11" ry="6" fill="#f59bb0" opacity=".7"/><ellipse cx="159" cy="122" rx="11" ry="6" fill="#f59bb0" opacity=".7"/><path d="m80 153 34 10 36-10v30l-36 10-34-10z" fill="#fffdf3" stroke="${c[2]}" stroke-width="2.5"/><path d="M114 163v30m-26-30 17 5m18 0 19-5" stroke="${c[2]}" stroke-width="2" stroke-linecap="round"/><path d="m109 63 6-12 6 12-6 7z" fill="#fff8cb"/>${kind==='berry'?'<path d="m72 56 43-47 44 47q-42 15-87 0" fill="#7254be" stroke="#5d449d" stroke-width="3"/><path d="m114 27 3 7 8 1-6 5 2 7-7-4-6 4 1-7-5-5 8-1z" fill="#ffe79a"/>':''}</svg>`};
const totalStudied=()=>Object.values(state.days).reduce((a,b)=>a+b,0);
function player(){const total=totalStudied();return {total,xp:total*10,level:Math.floor(total/50)+1,progress:total%50/50*100}}
function rewardBadges(){const total=totalStudied();return [{emoji:'🌱',name:'はじめの一歩',hint:'はじめて1語学ぶ',earned:total>=1},{emoji:'🔥',name:'3日間の習慣',hint:'3日連続で学ぶ',earned:streak()>=3},{emoji:'🌟',name:'ことばコレクター',hint:'10語を習得する',earned:learned()>=10},{emoji:'👑',name:'100語の積み重ね',hint:'のべ100語学ぶ',earned:total>=100}]}
function badgeShelf(){return `<section class="badge-panel"><div class="section-heading"><h2>MILESTONES / 学習の節目</h2><span class="badge-count">${rewardBadges().filter(b=>b.earned).length} / 4 GET</span></div><div class="badge-grid">${rewardBadges().map(b=>`<div class="achievement ${b.earned?'earned':'locked'}"><span class="achievement-medal" aria-hidden="true">${b.emoji}</span><strong>${b.name}</strong><small>${b.earned?'達成済み':b.hint}</small></div>`).join('')}</div></section>`}
function deckTile(key){const d=decks[key],count=words.filter(w=>w.deck===key).length,n=learned(key),basic=key==='basic';return `<button class="deck-card ${d.color}" data-deck="${key}"><div class="deck-scene"><span class="world-number">COLLECTION / ${basic?'01':'02'}</span><span class="deck-display">${basic?'Every<br>day.':'Beyond<br>basic.'}</span><span class="deck-arrow" aria-hidden="true">↗</span><span class="world-label">${basic?'THE ESSENTIALS':'THE NEXT CHAPTER'}</span></div><div class="deck-info"><div class="deck-tag">${basic?'日常を、もっと自由に。':'表現を、もう一段深く。'}</div><h3>${d.title}</h3><p>${basic?'毎日の会話で使える、身近な英単語。':'英検準1級の語彙で、伝わる言葉を増やす。'}</p><div class="deck-bottom"><span>${n} / ${count} 語 習得</span><span>学習する ${icon('arrow')}</span></div><div class="progress-track"><i style="width:${n/count*100}%"></i></div></div></button>`}
let feedback=null;
let pronunciation=null,audioSlow=false;
try{audioSlow=localStorage.getItem('kioku-audio-slow')==='true'}catch{}
const audioSources=new Map(words.flatMap(w=>[[w.word,`/audio/${w.id}-word.mp3`],[w.example,`/audio/${w.id}-example.mp3`]]));
const audioControl=()=>`<button class="audio-speed ${audioSlow?'slow':''}" data-action="audio-speed" aria-pressed="${audioSlow}" aria-label="発音の速度を切り替える">${audioSlow?'0.75× ゆっくり':'1× 標準速度'}</button>`;
function speakText(text,button){pronunciation??=createPronunciationPlayer({onError:toast});pronunciation.stop();button.classList.add('speech-playing');button.setAttribute('aria-busy','true');pronunciation.play({text,src:audioSources.get(text),slow:audioSlow,onDone:()=>{button.classList.remove('speech-playing');button.removeAttribute('aria-busy')}})}

function effects(){if(!feedback)return '';return `<div id="celebration" class="celebration ${feedback.kind}" role="status"><div class="feedback-bubble"><span>${feedback.kind==='success'?'🌟':'💪'}</span>${feedback.text}</div>${feedback.kind==='success'?Array.from({length:22},(_,i)=>`<i class="confetti" style="--i:${i};--x:${(i*47)%100}%;--color:${['#ffc85e','#a795ef','#73d9bd','#ff91aa'][i%4]}"></i>`).join(''):''}</div>`}
function render(){const root=document.querySelector('#app');root.innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-page="home"><span class="brand-mark">k<span>✦</span></span>kioku<span class="brand-dot">.</span></a><div class="sidebar-caption">WORDS CHANGE YOUR WORLD.</div><nav>${nav()}</nav><div class="side-note"><span class="side-note-symbol">↗</span><p>A little, every day.</p><span>小さな習慣で、遠くまで。</span></div><button class="profile" data-action="account"><span class="avatar">${icon('user')}</span><span>${account?esc(account.name):'マイアカウント'}<small>${account?'ログイン中 · 記録を同期':'ログイン・新規登録'}</small></span>${icon('chevron')}</button></aside><main><header class="topbar"><span class="breadcrumb"><span class="header-brand">kioku<span>monster</span></span><span class="desktop-crumb">MY EDITION /</span> ${page==='home'?'ホーム':page==='words'?'単語帳':page==='stats'?'学習記録':'カード学習'}</span><div class="player-hud"><span class="hud-level">Lv.${player().level}</span><span class="hud-xp">${player().xp} XP</span><button data-action="goal" class="hud-streak" aria-label="1日の目標を変更">${streak()} DAYS</button></div><button class="mobile-account" data-action="account" aria-label="アカウント">${icon('user')}</button></header><div class="content ${page==='study'?'study-content':''}">${page==='home'?home():page==='words'?wordPage():page==='stats'?stats():study()}</div><footer>kioku. <span>Make words. Make worlds.</span><span>英検®は公益財団法人 日本英語検定協会の登録商標です。本アプリは同協会の承認・推奨を受けたものではありません。</span></footer></main><nav class="mobile-nav">${nav()}</nav>${modal?modalHtml():''}${effects()}`;bind();}
function nav(){return [['home','home','ホーム'],['study','star','学習する'],['words','book','単語帳'],['stats','chart','学習記録']].map(([p,i,t])=>`<button class="nav-item ${page===p?'active':''}" data-page="${p}">${icon(i)}<span>${t}</span>${p==='home'?'<i></i>':''}</button>`).join('')}
function home(){const p=player(),progress=Math.min(100,today()/state.goal*100);return `<div class="page-heading"><div><div class="eyebrow">THE DAILY WORD / YOUR PERSONAL EDITION</div><h1>${account?esc(account.name)+'さんの、':'今日の、'}新しい視点。</h1><p>知っている言葉が、見える世界を変えていく。</p></div><span class="date-chip">${new Date().toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric'}).toUpperCase()}</span></div><section class="hero"><div class="hero-copy"><span class="hero-tag">SMALL HABIT. BIG DIFFERENCE.</span><h2>Make words.<br><span>Make worlds.</span></h2><p>ひとつの言葉から、世界を広げよう。<br>今日も10語、自分のペースで。</p><button class="primary light" data-action="start">今日の10語をはじめる ${icon('arrow')}</button><div class="hero-meta">${icon('clock')} 10 WORDS <span>/</span> ABOUT 3 MINUTES</div></div><div class="editorial-art" aria-hidden="true"><span class="art-index">KIOKU — LANGUAGE & CULTURE</span><div class="type-orbit">Aa<span>↗</span></div><span class="art-caption">A NEW WORD.<br>A NEW WAY TO SEE.</span><span class="art-edition">VOL.<b>01</b></span></div></section><div class="dashboard-grid"><section class="quest-panel"><div class="section-heading"><h2><span class="section-index">01</span> 今日の学習</h2><button class="text-button" data-action="goal">目標を変更 ${icon('chevron')}</button></div><div class="quest-main"><div><strong>${today()}<small> / ${state.goal} 語</small></strong><p>${today()>=state.goal?'今日の目標を達成しました。':'小さな積み重ねを、自分の力に。'}</p></div><span class="goal-percent">${Math.round(progress)}<small>%</small></span></div><div class="progress-track"><i style="width:${progress}%"></i></div></section><section class="buddy-panel"><div><span class="buddy-label">YOUR MOMENTUM</span><strong>Level ${p.level}<span>${p.xp} XP</span></strong><div class="progress-track"><i style="width:${p.progress}%"></i></div><small>次のレベルまで ${50-p.total%50}語</small></div><span class="momentum-arrow" aria-hidden="true">↗</span></section></div><div class="section-heading world-heading"><div><span class="eyebrow">THE COLLECTION</span><h2>次に出会う、言葉たち。</h2></div><button class="text-button" data-page="words">単語帳を見る ${icon('arrow')}</button></div><div class="deck-grid">${Object.keys(decks).map(deckTile).join('')}</div><div class="bottom-grid"><section class="review-banner"><div><span class="eyebrow">REVISIT & REMEMBER</span><h3>もう一度出会うと、記憶になる。</h3><p>復習する単語 <strong>${due()}語</strong></p></div><button class="secondary" data-action="review">復習する ${icon('arrow')}</button></section><section class="tiny-stats"><div><strong>${streak()}<small>日</small></strong><p>連続学習</p></div><div><strong>${learned()}<small>語</small></strong><p>習得した単語</p></div></section></div>${badgeShelf()}`}
function start(deck=selected,mode='all'){feedback=null;pronunciation?.stop();selected=deck;let queue=queueFor(words,state.records,deck,mode);if(!queue.length){toast(mode==='review'?'この単語帳には復習待ちの単語がありません。':'対象の単語がありません。');return}session={queue,index:0,revealed:false,known:0,answered:0,done:false};page='study';render();window.scrollTo(0,0)}
function study(){if(!session)return `<div class="page-heading"><div><div class="eyebrow">PICK YOUR COLLECTION</div><h1>次は、どの言葉を学ぶ？</h1><p>1回10語。いまの自分に合うコレクションから。</p></div></div><div class="deck-grid">${Object.keys(decks).map(deckTile).join('')}</div>`;
if(session.done)return `<div class="completion"><div class="completion-stars">✦ <span>🌟</span> ✦</div><div class="completion-buddy">${mascot(true)}<span class="finish-crown">👑</span></div><div class="eyebrow">SESSION COMPLETE</div><h1>今日の10語を、力に。</h1><p>${session.answered}語の学習が完了しました。<br>次の一歩も、自分のペースで。</p><div class="xp-reward">+${session.answered*10} XP <span>SESSION REWARD</span></div><div class="result-grid"><div><span class="result-emoji">🙌</span><strong>${session.known}<small>語</small></strong><span>覚えていた！</span></div><div><span class="result-emoji">🌱</span><strong>${session.answered-session.known}<small>語</small></strong><span>復習する単語</span></div></div><p class="muted">復習を重ねて、確かな記憶に。</p><button class="primary" data-action="start">続けて学習する ${icon('arrow')}</button><button class="text-button" data-page="home">ホームにもどる</button></div>`;
const w=session.queue[session.index];return `<div class="study-audio-control">${audioControl()}</div><div class="study-header"><button class="text-button" data-action="exit">${icon('close')} おわる</button><span>${selected==='basic'?'DAILY ENGLISH':'ADVANCED ENGLISH'}</span><strong>${session.index+1}<small> / ${session.queue.length}</small></strong></div><div class="progress-track study-progress"><i style="width:${session.index/session.queue.length*100}%"></i></div><div class="study-buddy"><span class="study-buddy-art">${mascot(true,selected==='pre1'?'berry':'mint')}</span><p>${session.revealed?'なるほど！声に出して言ってみよう。':'このことば、どんな意味かな？'}<small>${session.revealed?'まちがえても大丈夫。何度でもチャレンジ！':'わからなくても、タップして見てみよう！'}</small></p></div><article class="flashcard ${session.revealed?'revealed':''} ${selected==='pre1'?'purple-card':''}"><div class="card-toolbar"><span class="level-tag">${selected==='basic'?'BASIC WORD':'ADVANCED WORD'}</span><button class="icon-button ${state.bookmarks.includes(w.id)?'bookmarked':''}" data-action="bookmark" aria-label="単語を保存" aria-pressed="${state.bookmarks.includes(w.id)}">${icon('star')}</button></div><div class="word-front"><span class="word-pos">${w.pos}</span><h1>${w.word}</h1><div class="pronunciation">${w.ipa}<button class="icon-button" data-speak="${w.word}" aria-label="発音を聞く">${icon('sound')}</button></div></div>${session.revealed?`<div class="word-back"><h2><span>💡</span> ${w.meaning}</h2><div class="example"><span>IN CONTEXT</span><p>${w.example}</p><small>${w.translation}</small><button class="icon-button" data-speak="${w.example}" aria-label="例文を聞く">${icon('sound')}</button></div></div>`:`<button class="reveal-area" data-action="reveal"><span class="mystery-icons">? <span>✨</span> ?</span><span>タップして意味を表示</span></button>`}</article><div class="study-controls">${session.revealed?`<div class="answer-buttons"><button class="again" data-answer="no"><span>🌱</span> もう一度<small>復習リストへ</small></button><button class="primary" data-answer="yes"><span>🙌</span> 覚えた！<small>+10 XP</small></button></div>`:`<button class="primary reveal-button" data-action="reveal">意味を表示 ${icon('arrow')}</button>`}<span class="keyboard-hint">${session.revealed?'← もう一度　 /　 覚えた →':'スペースキーでも意味を表示'}</span></div>`}
function wordPage(){let list=words.filter(w=>w.deck===selected&&(filter==='all'||filter==='saved'&&state.bookmarks.includes(w.id)||filter==='weak'&&state.records[w.id]&&!state.records[w.id].known||filter==='learned'&&state.records[w.id]?.level>=2)&&(`${w.word} ${w.meaning}`).toLowerCase().includes(search.toLowerCase()));return `<div class="page-heading"><div><div class="eyebrow">WORD COLLECTION</div><h1>言葉を、自分のものに。</h1><p>検索、保存、復習。あなたの語彙をここに。</p></div></div><div class="tabs">${Object.entries(decks).map(([key,d])=>`<button class="${key===selected?'selected':''}" data-select="${key}">${d.title}<span>${words.filter(w=>w.deck===key).length}</span></button>`).join('')}</div><div class="library-audio-control">${audioControl()}<span>アメリカ英語のお手本音声</span></div><div class="word-tools"><label class="search">${icon('search')}<input id="search" placeholder="単語・意味を検索" value="${esc(search)}" aria-label="単語・意味を検索"></label><select id="filter" aria-label="単語の絞り込み">${[['all','すべての単語'],['saved','保存した単語'],['weak','苦手な単語'],['learned','習得済み']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="word-list">${list.length?list.map(w=>`<article class="word-row"><button class="icon-button ${state.bookmarks.includes(w.id)?'bookmarked':''}" data-save="${w.id}" aria-label="${w.word}を保存" aria-pressed="${state.bookmarks.includes(w.id)}">${icon('star')}</button><div><h3>${w.word}</h3><p><span>${w.pos}</span> ${w.meaning}</p></div><span class="status-tag ${state.records[w.id]?.level>=2?'mastered':''}">${state.records[w.id]?.level>=2?'習得済み':state.records[w.id]?'学習中':'未学習'}</span><button class="icon-button" data-speak="${w.word}" aria-label="${w.word}の発音">${icon('sound')}</button></article>`).join(''):'<div class="empty">該当する単語がありません。</div>'}</div><p class="list-note">${list.length}語を表示 · 独自に選定した対策用語彙です。公式の出題語彙一覧ではありません。</p><button class="primary word-start" data-action="start">この単語帳で学習する ${icon('arrow')}</button>`}
function stats(){const max=Math.max(state.goal,...Object.values(state.days));let total=Object.values(state.days).reduce((a,b)=>a+b,0);return `<div class="page-heading"><div><div class="eyebrow">YOUR PROGRESS</div><h1>積み重ねが、見えてくる。</h1><p>日々の学習と、身についた言葉の記録。</p></div><button class="secondary" data-action="goal">目標を変更</button></div><div class="stat-grid"><section class="stat-card"><div class="stat-icon peach">${icon('flame')}</div><div><span class="stat-label">連続学習</span><div class="stat-value">${streak()}<small>日</small></div></div></section><section class="stat-card"><div class="stat-icon sage">${icon('book')}</div><div><span class="stat-label">累計学習回数</span><div class="stat-value">${total}<small>語</small></div></div></section><section class="stat-card"><div class="stat-icon lavender">${icon('check')}</div><div><span class="stat-label">覚えた単語</span><div class="stat-value">${learned()}<small>語</small></div></div></section></div><section class="chart-panel"><div class="section-heading"><h2>この1週間の学習</h2><span class="muted">1日の目標 ${state.goal}語</span></div><div class="bar-chart">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let n=state.days[dayKey(d)]||0;return `<div class="bar-col"><span>${n}</span><div class="bar-track"><div class="bar ${i===6?'today':''}" style="height:${Math.max(2,n/max*100)}%"></div></div><label>${d.toLocaleDateString('ja-JP',{weekday:'short'})}</label></div>`}).join('')}</div></section><section class="chart-panel"><h2>単語帳ごとの進み具合</h2>${Object.entries(decks).map(([k,d])=>{let count=words.filter(w=>w.deck===k).length;return `<div class="deck-stat"><div><strong>${d.title}</strong><span>${learned(k)} / ${count} 語</span></div><div class="progress-track"><i style="width:${learned(k)/count*100}%"></i></div></div>`}).join('')}</section>${badgeShelf()}<p class="list-note">「覚えた」を2回選んだ単語を習得済みとして数えます。${account?'学習記録はアカウントに保存されます。':'ゲストの記録はこのブラウザに保存されます。'}</p>`}
function modalHtml(){return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="閉じる">${icon('close')}</button>${modal==='goal'?`<div class="eyebrow">YOUR OWN PACE</div><h2 id="modal-title">1日の目標を決めよう</h2><p>無理なく続けられる語数がおすすめです。</p><div class="goal-choices">${[5,10,20,30].map(n=>`<button class="${state.goal===n?'selected':''}" data-goal="${n}">${n}<small>語</small></button>`).join('')}</div>`:account?`<div class="eyebrow">YOUR ACCOUNT</div><h2 id="modal-title">こんにちは、${esc(account.name)}さん。</h2><p>${esc(account.email)}<br>学習記録はアカウントに保存しています。</p><button class="primary" data-action="export">学習記録を書き出す</button><button class="text-button" data-action="signout">ログアウト</button>`:serverAuth?`<div class="brand modal-brand">kioku.</div><h2 id="modal-title">${authMode==='signup'?'小さな習慣を、はじめよう。':'おかえりなさい。'}</h2><p>ログインすると、あなたの学習記録を保存できます。</p><form id="auth-form">${authMode==='signup'?'<label>お名前<input name="name" autocomplete="nickname" maxlength="40" placeholder="お名前" required></label>':''}<label>メールアドレス<input name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254"></label><label>パスワード<input name="password" type="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" placeholder="10文字以上" required minlength="10" maxlength="128"></label><p id="auth-error" role="alert"></p><button type="submit" class="primary">${authMode==='signup'?'アカウントを作成':'ログイン'} ${icon('arrow')}</button></form><button class="text-button" data-action="toggle-auth">${authMode==='signup'?'すでにアカウントをお持ちの方':'はじめての方はこちら · 新規登録'}</button><p class="auth-footnote">ゲストの記録とアカウントの記録は別々に保存されます。</p>`:`<div class="brand modal-brand">kioku.</div><h2 id="modal-title">あなたの学びを、ここから。</h2><p>公開版はChatGPTアカウントでログインして使えます。</p><a class="primary" href="/signin-with-chatgpt?return_to=%2F" target="_top">${icon('user')} ChatGPTでログイン</a><a class="text-button" href="/signout-with-chatgpt?return_to=%2F" target="_top">ログアウト</a><div class="account-note">${icon('leaf')}<div><strong>学習記録について</strong><p>この静的プレビューの記録はブラウザに保存されます。アカウント別の記録保存には、同梱サーバーを起動してください。</p></div></div><button class="secondary" data-action="export">学習記録を書き出す</button>`}</section></div>`}

function bind(){const form=document.querySelector('#auth-form');if(form)form.onsubmit=submitAuth;document.querySelectorAll('[data-page]').forEach(el=>el.onclick=e=>{e.preventDefault();pronunciation?.stop();if(page==='study'&&session&&!session.done&&session.answered){modal=null;if(!confirm('学習を終了しますか？ここまでの記録は保存されます。'))return}page=el.dataset.page;modal=null;render();scrollTo(0,0)});document.querySelectorAll('[data-deck]').forEach(el=>el.onclick=()=>start(el.dataset.deck));document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>{selected=el.dataset.select;render()});document.querySelectorAll('[data-speak]').forEach(el=>el.onclick=()=>speakText(el.dataset.speak,el));document.querySelectorAll('[data-save]').forEach(el=>el.onclick=()=>toggleSave(el.dataset.save));document.querySelectorAll('[data-answer]').forEach(el=>el.onclick=()=>answer(el.dataset.answer==='yes'));document.querySelectorAll('[data-goal]').forEach(el=>el.onclick=()=>{state.goal=Number(el.dataset.goal);save();modal=null;render();toast('1日'+state.goal+'語に変更しました')});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));const input=document.querySelector('#search');if(input)input.oninput=()=>{const pos=input.selectionStart;search=input.value;render();const next=document.querySelector('#search');next.focus();next.setSelectionRange(pos,pos)};const f=document.querySelector('#filter');if(f)f.onchange=()=>{filter=f.value;render()};const backdrop=document.querySelector('.modal-backdrop');if(backdrop)backdrop.onclick=e=>{if(e.target===backdrop){modal=null;render()}}}
function toggleSave(id){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render()}
function answer(known){if(!session||session.done||!session.revealed)return;pronunciation?.stop();let w=session.queue[session.index];state.records[w.id]=review(state.records[w.id],known);state.days[dayKey()]=today()+1;session.answered++;if(known)session.known++;session.index++;session.revealed=false;if(session.index>=session.queue.length)session.done=true;save();feedback={kind:known||session.done?'success':'retry',text:session.done?'学習完了！ +'+session.answered*10+' XP':known?'+10 XP':'ナイスチャレンジ！ +10 XP'};const thisFeedback=feedback;render();setTimeout(()=>{if(feedback===thisFeedback){feedback=null;document.querySelector('#celebration')?.remove()}},1800)}
function action(a){if(a==='audio-speed'){audioSlow=!audioSlow;try{localStorage.setItem('kioku-audio-slow',String(audioSlow))}catch{}pronunciation?.stop();render();return}if(a==='signout'){logout();return}if(a==='toggle-auth'){authMode=authMode==='signin'?'signup':'signin';render();return}if(a==='start')start();if(a==='reveal'){session.revealed=true;render()}if(a==='bookmark')toggleSave(session.queue[session.index].id);if(a==='exit'){if(!session.answered||confirm('学習を終了しますか？ここまでの記録は保存されます。')){session=null;page='home';render()}}if(a==='account'||a==='goal'){modal=a;render()}if(a==='close'){modal=null;render()}if(a==='review'){const w=words.find(w=>state.records[w.id]?.due<=Date.now());if(w)start(w.deck,'review');else toast('今は復習待ちの単語がありません。新しい単語を学んでみましょう。')}if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`kioku-${dayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学習記録を書き出しました')}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render();return}if(page!=='study'||!session||session.done||modal||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.code==='Space'&&!session.revealed){e.preventDefault();action('reveal')}else if(session.revealed&&e.key==='ArrowLeft')answer(false);else if(session.revealed&&e.key==='ArrowRight')answer(true)});
async function submitAuth(e){e.preventDefault();const form=e.currentTarget,button=form.querySelector('button');button.disabled=true;button.textContent='処理中…';try{const values=Object.fromEntries(new FormData(form));const r=await fetch('/api/'+authMode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const data=await r.json();if(!r.ok)throw Error(data.error);account=data.user;state=data.data;session=null;page='home';modal=null;render();toast('ログインしました。学習記録を同期します。')}catch(error){document.querySelector('#auth-error').textContent=error.message||'接続を確認してください。';button.disabled=false;button.textContent=authMode==='signup'?'アカウントを作成':'ログイン'}}
async function logout(){await saveQueue;try{const r=await fetch('/api/signout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();account=null;let guest;try{guest=JSON.parse(localStorage.getItem('kioku-v1'))}catch{}state=guest||{records:{},days:{},bookmarks:[],goal:10};modal=null;session=null;page='home';render();toast('ログアウトしました。')}catch{toast('ログアウトできませんでした。接続を確認してください。')}}
async function initialize(){try{const r=await fetch('/api/me');if(r.ok){const data=await r.json();serverAuth=true;account=data.user;if(account){const response=await fetch('/api/data');if(!response.ok)throw Error();state=(await response.json()).data}}}catch{toast('アカウントの読み込みに失敗しました。ページを再読み込みしてください。')}render()}
render();initialize();
